def redaguj(text):
    for old, new in REPLACEMENTS:
        text = text.replace(old, new)
    # Niektóre reguły doprecyzowują zwroty powstałe we wcześniejszym kroku.
    for old, new in REPLACEMENTS:
        text = text.replace(old, new)
    return text


def main():
    files = [ROOT/'raport'/name for name in ('00_streszczenie.md','01_problem_i_cel.md','04_dane_i_zrodla.md',
                                            '05_metodologia.md','06_wyniki.md','07_dyskusja_i_wnioski.md','08_odtworzenie_i_zrodla.md')]
    for path in files:
        before = path.read_text(encoding='utf-8')
        after = redaguj(before)
        assert redaguj(after) == after, 'Niejednoznaczna reguła redakcji: '+path.name
        path.write_text(after,encoding='utf-8')
    print('Zredagowano siedem fragmentów raportu; dane i obliczenia pozostają bez zmian.')


if __name__ == '__main__':
    main()
